<script setup lang="ts">
import type { InspectionDetailDto, IssueDto, PhotoUploadDto } from '~/types/api'
import { errorMessage, todayLocal, statusLabel } from '~/utils/format'
import { downloadWord } from '~/utils/wordDownload'
const props=defineProps<{id:string;returnTo?:string}>(),emit=defineEmits<{changed:[]}>()
const detail=ref<InspectionDetailDto|null>(null),error=ref(''),loading=ref(false),busy=ref(false),action=ref<'feedback'|'review'|''>(''),issue=ref<IssueDto|null>(null),notes=ref(''),date=ref(todayLocal()),photos=ref<PhotoUploadDto[]>([]),uploading=ref(false),failed=ref(false)
let sequence=0
async function load(){const request=++sequence;loading.value=true;error.value='';try{const value=await $fetch<InspectionDetailDto>(`/api/inspections/${props.id}`);if(request===sequence)detail.value=value}catch(e){if(request===sequence)error.value=errorMessage(e)}finally{if(request===sequence)loading.value=false}}
function begin(value:IssueDto,kind:'feedback'|'review'){issue.value=value;action.value=kind;notes.value='';date.value=todayLocal();photos.value=[];failed.value=false;error.value=''}
async function save(){if(!issue.value||!notes.value.trim()||busy.value||uploading.value||failed.value)return;busy.value=true;error.value='';try{await $fetch(`/api/issues/${issue.value.id}/${action.value}`,{method:'POST',body:{date:date.value,notes:notes.value,conclusion:notes.value,photoIds:photos.value.map(x=>x.id),revision:issue.value.revision},retry:0});action.value='';await load();emit('changed')}catch(e){error.value=errorMessage(e)}finally{busy.value=false}}
async function exportWord(){try{await downloadWord(`/api/inspections/${props.id}/export/record`,'检查记录.docx')}catch(e){error.value=errorMessage(e)}}
function closeAction(){if(busy.value||uploading.value)return;if((notes.value.trim()||photos.value.length)&&!window.confirm('办理内容尚未保存，放弃填写吗？'))return;action.value=''}
watch(()=>props.id,()=>{action.value='';detail.value=null;void load()},{immediate:true})
</script>
<template><div class="space-y-4"><UAlert v-if="error" :description="error" color="error" /><p v-if="loading" class="text-muted">正在读取检查…</p><template v-if="detail"><dl class="detail-grid"><div><dt>检查日期</dt><dd>{{ detail.inspection.date }}</dd></div><div><dt>检查人</dt><dd>{{ detail.inspection.inspector }}</dd></div><div><dt>检查类型</dt><dd>{{ detail.inspection.inspectionTypeName||'未分类' }}</dd></div><div><dt>检查对象</dt><dd>{{ detail.inspection.useName||'整个场所' }}</dd></div><div><dt>结果</dt><dd>{{ detail.inspection.result==='normal'?'正常':detail.inspection.result==='incomplete'?'未完成检查':'发现问题' }}</dd></div></dl><p v-if="detail.inspection.incompleteReason">{{ detail.inspection.incompleteReason }}</p><p v-if="detail.inspection.notes">{{ detail.inspection.notes }}</p><div v-for="(item,index) in detail.issues.filter(x=>!x.voided)" :key="item.id" class="border-t border-default pt-3 space-y-2"><div class="flex justify-between gap-2"><strong>问题 {{ index+1 }}</strong><UBadge :color="item.status==='closed'?'success':'warning'">{{ statusLabel(item.status) }}</UBadge></div><p>{{ item.description }}</p><p v-if="item.requirement" class="text-sm text-muted">整改要求：{{ item.requirement }}</p><p class="text-sm">{{ item.responsibleUnit }} · 期限 {{ item.deadline }}</p><p v-if="item.feedbackNotes" class="text-sm">反馈：{{ item.feedbackNotes }}</p><p v-if="item.reviewConclusion" class="text-sm">复查：{{ item.reviewConclusion }}</p><IssuePhotos v-if="detail.photos.some(x=>x.issueId===item.id)" :photos="detail.photos.filter(x=>x.issueId===item.id)" /><div class="flex flex-wrap gap-2"><IssueProgress v-if="item.status!=='closed'" :issue="item" @saved="load();emit('changed')" /><UButton v-if="item.status!=='closed'" label="整改反馈" size="sm" variant="outline" @click="begin(item,'feedback')" /><UButton v-if="item.status==='feedback'" label="复查完成" size="sm" @click="begin(item,'review')" /></div></div><IssuePhotos v-if="detail.photos.some(x=>!x.issueId)" :photos="detail.photos.filter(x=>!x.issueId)" label="现场" /><div class="flex gap-2"><UButton label="导出 Word" size="sm" variant="outline" @click="exportWord" /><UButton :to="{path:`/inspections/${id}`,query:{returnTo}}" label="查看完整记录" size="sm" color="neutral" variant="link" /></div></template><UModal :open="!!action" :title="action==='review'?'复查完成':'整改反馈'" :dismissible="!busy&&!uploading" :close="!busy&&!uploading" @update:open="value=>{if(!value)closeAction()}"><template #body><div class="space-y-3"><UAlert v-if="error" :description="error" color="error" /><UFormField :label="action==='review'?'复查日期':'反馈日期'" required><UInput v-model="date" type="date" :min="detail?.inspection.date" :max="todayLocal()" :disabled="busy" /></UFormField><UFormField :label="action==='review'?'复查结论':'整改说明'" required><UTextarea v-model="notes" class="w-full" :disabled="busy" /></UFormField><PhotoUploader v-model="photos" :phase="action==='review'?'review':'after'" :disabled="busy" @busy="uploading=$event" @failed="failed=$event" /></div></template><template #footer><UButton label="取消" color="neutral" variant="outline" :disabled="busy||uploading" @click="closeAction" /><UButton label="保存" :loading="busy" :disabled="uploading||failed||!notes.trim()" @click="save" /></template></UModal></div></template>
